// Turns the token model into CSS (docs) and shadcn registry fields (dga-style).

import { BREAKPOINTS, MODE_MIN_WIDTH } from "./fixes";
import type { Model } from "./model";
import type { Mode, ThemeToken } from "./source";

export type Vars = [name: string, value: string][];

const HEADER =
  "/* Generated by scripts/generate-tokens.ts from tokens/tokens.json (Figma). Do not edit by hand. */";

export const FONT_STACK = 'var(--font-sans, "IBM Plex Sans Arabic"), system-ui, sans-serif';

/** `{token}` → `var(--token)`. */
export function toCss(value: string) {
  return value.replace(/\{([^}]+)\}/g, "var(--$1)");
}

/** Font tokens that are Figma style names ("Medium Italic"), not CSS values. Dropped. */
export const ITALIC_WEIGHTS = /^(primitive-)?font-weight-(.*-)?italic$/;

// ---------------------------------------------------------------------------
// shadcn variables, mapped onto DGA semantic tokens.
// ---------------------------------------------------------------------------

export const SHADCN_VARS: Record<string, string> = {
  background: "background-body",
  foreground: "text-default",
  card: "background-card",
  "card-foreground": "text-default",
  popover: "background-menu",
  "popover-foreground": "text-default",
  primary: "background-primary",
  "primary-foreground": "text-oncolor-primary",
  secondary: "button-background-neutral-default",
  "secondary-foreground": "text-default",
  muted: "background-neutral-50",
  "muted-foreground": "text-secondary-paragraph",
  accent: "background-neutral-100",
  "accent-foreground": "text-default",
  destructive: "background-error",
  "destructive-foreground": "text-oncolor-primary",
  border: "border-neutral-secondary",
  input: "border-neutral-primary",
  ring: "border-black",
  "chart-1": "charts-green",
  "chart-2": "charts-gold",
  "chart-3": "charts-blue",
  "chart-4": "charts-lavender",
  "chart-5": "charts-red",
  sidebar: "background-white",
  "sidebar-foreground": "text-default",
  "sidebar-primary": "background-primary",
  "sidebar-primary-foreground": "text-oncolor-primary",
  "sidebar-accent": "background-neutral-100",
  "sidebar-accent-foreground": "text-default",
  "sidebar-border": "border-neutral-secondary",
  "sidebar-ring": "border-black",
};

export const shadcnVars = (): Vars => [
  ...Object.entries(SHADCN_VARS).map(([k, v]) => [k, `var(--${v})`] as [string, string]),
  ["radius", "var(--radius-sm)"],
];

// ---------------------------------------------------------------------------
// Short semantic aliases: Figma name without its category prefix
// (background-body → bg-body, text-primary → text-primary, border-primary → border-primary).
// ---------------------------------------------------------------------------

const ALIAS_NAMESPACE = {
  background: "background-color",
  text: "text-color",
  border: "border-color",
} as const;

/** shadcn names whose meaning matches the DGA token, so the alias may take them over. */
const SHADCN_SAME_MEANING = new Set(["text-primary", "border-primary", "background-card"]);

export type Alias = { utility: string; variable: string; token: string };

export function shortAliases(model: Model, paletteKeys: Set<string>): Alias[] {
  const shadcnKeys = new Set(Object.keys(SHADCN_VARS));
  const aliases: Alias[] = [];
  for (const name of [...model.themes.keys()].sort()) {
    const prefix = name.split("-")[0] as keyof typeof ALIAS_NAMESPACE;
    const namespace = ALIAS_NAMESPACE[prefix];
    if (!namespace) continue;
    const key = name.slice(prefix.length + 1);
    if (!key) continue;
    if (paletteKeys.has(key)) continue; // bg-white / bg-neutral-50 stay palette colours
    if (shadcnKeys.has(key) && !SHADCN_SAME_MEANING.has(name)) continue;
    const utility = { background: "bg", text: "text", border: "border" }[prefix];
    aliases.push({ utility: `${utility}-${key}`, variable: `${namespace}-${key}`, token: name });
  }
  return aliases;
}

// ---------------------------------------------------------------------------
// Palettes
// ---------------------------------------------------------------------------

/** Readable hue aliases for the DGA brand primitives. */
const HUE_ALIASES: [RegExp, string][] = [
  [/^colors-primary-sa-flag-(\d+)(-primary)?$/, "sa-flag-$1"],
  [/^colors-secondary-gold-(\d+)(-primary)?$/, "gold-$1"],
  [/^colors-tertiary-lavender-(\d+)(-primary)?$/, "lavender-$1"],
  [/^colors-base-(white|black)$/, "$1"],
];

export function paletteVars(model: Model) {
  const figma: Vars = [];
  const hues: Vars = [];
  for (const [name, primitive] of model.primitives) {
    if (!name.startsWith("colors-") || !/^#|^\{/.test(primitive.value)) continue;
    figma.push([`color-${name.slice("colors-".length)}`, `var(--${name})`]);
    for (const [pattern, replacement] of HUE_ALIASES) {
      if (pattern.test(name))
        hues.push([`color-${name.replace(pattern, replacement)}`, `var(--${name})`]);
    }
  }
  return { figma, hues };
}

// ---------------------------------------------------------------------------
// CSS blocks
// ---------------------------------------------------------------------------

export function themeVars(model: Model, mode: Mode): Vars {
  const vars: Vars = [];
  for (const token of model.themes.values()) vars.push([token.name, toCss(token[mode])]);
  return vars;
}

/**
 * Figma stores a font weight as the name of the font style ("Semibold"), which is not a CSS
 * font-weight: `font-weight: Semibold` is invalid and falls back to 400, so every font-medium,
 * font-semibold and font-bold rendered as regular. CSS needs the number.
 */
export const FONT_WEIGHT_NUMBERS: Record<string, string> = {
  regular: "400",
  medium: "500",
  semibold: "600",
  bold: "700",
};

export const fontWeightNumber = (name: string, value: string) => {
  const key = /^(?:primitive-)?font-weight-(regular|medium|semibold|bold)$/.exec(name)?.[1];
  return key ? (FONT_WEIGHT_NUMBERS[key] ?? value) : value;
};

function primitiveVars(model: Model): Vars {
  const vars: Vars = [];
  for (const [name, primitive] of model.primitives) {
    if (ITALIC_WEIGHTS.test(name)) continue;
    const value = name.startsWith("primitive-font-family-") ? FONT_STACK : toCss(primitive.value);
    vars.push([name, fontWeightNumber(name, value)]);
  }
  return vars;
}

function responsiveVars(model: Model) {
  const mobile: Vars = [];
  const tablet: Vars = [];
  const desktop: Vars = [];
  for (const [name, token] of model.responsive) {
    if (ITALIC_WEIGHTS.test(name)) continue;
    const { values } = token;
    mobile.push([name, toCss(values.mobile)]);
    if (values.tablet !== values.mobile) tablet.push([name, toCss(values.tablet)]);
    if (values.desktop !== values.tablet) desktop.push([name, toCss(values.desktop)]);
  }
  return { mobile, tablet, desktop };
}

function effectVars(model: Model): Vars {
  return [
    ...model.shadows.map((s) => [s.name, s.layers.join(", ")] as [string, string]),
    ...model.blurs.map((b) => [b.name, b.value] as [string, string]),
  ];
}

/** Everything that goes on :root (light theme, mobile viewport). */
export function rootVars(model: Model): Vars {
  return [
    ...primitiveVars(model),
    ...responsiveVars(model).mobile,
    ...effectVars(model),
    ...themeVars(model, "light"),
    ...shadcnVars(),
  ];
}

export const lightScopeVars = (model: Model): Vars => [
  ...themeVars(model, "light"),
  ...shadcnVars(),
];

/** Dark scope re-declares every semantic token, so nested [data-theme] sections resolve correctly. */
export const darkScopeVars = (model: Model): Vars => [
  ...themeVars(model, "dark"),
  ...shadcnVars(),
  // No shadows in dark mode: elevation is shown with borders and lighter surfaces.
  ...model.shadows.map((s) => [s.name, "0 0 #0000"] as [string, string]),
];

export const viewportVars = (model: Model) => {
  const { tablet, desktop } = responsiveVars(model);
  return { tablet, desktop };
};

// ---------------------------------------------------------------------------
// Tailwind @theme
// ---------------------------------------------------------------------------

const TEXT_SIZES = [
  "display-2xl",
  "display-xl",
  "display-lg",
  "display-md",
  "display-sm",
  "display-xs",
  "text-xl",
  "text-lg",
  "text-md",
  "text-sm",
  "text-xs",
  "text-2xs",
];

export function tailwindTheme(model: Model) {
  const palette = paletteVars(model);
  const paletteKeys = new Set(
    [...palette.figma, ...palette.hues].map(([n]) => n.slice("color-".length)),
  );
  const aliases = shortAliases(model, paletteKeys);

  const fonts: Vars = [
    ["font-sans", "var(--font-family-text)"],
    ["font-display", "var(--font-family-display)"],
  ];

  const semantic: Vars = [...model.themes.values()].map((t: ThemeToken) => [
    `color-${t.name}`,
    `var(--${t.name})`,
  ]);
  const shadcn: Vars = Object.keys(SHADCN_VARS).map((k) => [`color-${k}`, `var(--${k})`]);

  const text: Vars = [];
  for (const size of TEXT_SIZES) {
    const key = size.replace(/^text-/, "");
    text.push([`text-${key}`, `var(--typo-size-${size})`]);
    text.push([`text-${key}--line-height`, `var(--line-heights-${size})`]);
    const style = model.textStyles.find(
      (s) => s.name.toLowerCase().startsWith(size.replace("-", " ")) && s.name.endsWith("/Regular"),
    );
    if (style && style.letterSpacing !== "0%") {
      text.push([
        `text-${key}--letter-spacing`,
        `${Number.parseFloat(style.letterSpacing) / 100}em`,
      ]);
    }
  }
  text.push(
    ["text-base", "var(--typo-size-text-md)"],
    ["text-base--line-height", "var(--line-heights-text-md)"],
  );

  const weights: Vars = ["regular", "medium", "semibold", "bold"].map((w) => [
    `font-weight-${w}`,
    `var(--font-weight-${w})`,
  ]);
  weights.push(["font-weight-normal", "var(--font-weight-regular)"]);

  const radius: Vars = ["none", "xs", "sm", "md", "lg", "xl", "full"].map((r) => [
    `radius-${r}`,
    `var(--radius-${r})`,
  ]);
  radius.push(["radius-card", "var(--card-radius)"]);
  // shadcn class names above xl clamp to the largest DGA radius.
  for (const r of ["2xl", "3xl", "4xl"]) radius.push([`radius-${r}`, "var(--radius-xl)"]);

  const shadows: Vars = model.shadows.map((s) => [s.name, `var(--${s.name})`]);
  const blurs: Vars = model.blurs.map((b) => [
    b.name.replace("backdrop-blur-", "blur-"),
    `var(--${b.name})`,
  ]);

  const containers: Vars = [...model.primitives.keys()]
    .filter((n) => n.startsWith("width-"))
    .map((n) => [`container-${n.slice("width-".length)}`, `var(--${n})`]);
  containers.push(
    ["container-paragraph", "var(--paragraph-max-width)"],
    ["container-content", "var(--container-max-width-desktop)"],
  );

  // Component and layout spacing (p-card-lg-padding, gap-section-gap …). The t-shirt
  // spacing-xs … spacing-11xl aliases map 1:1 onto Tailwind's numeric scale, so they are not repeated.
  const spacing: Vars = [...model.responsive.values()]
    .filter((t) => t.group === "Spacing" && !t.name.startsWith("spacing-"))
    .map((t) => [`spacing-${t.name}`, `var(--${t.name})`]);

  const breakpoints: Vars = Object.entries(BREAKPOINTS).map(([k, v]) => [`breakpoint-${k}`, v]);

  const aliasVars: Vars = aliases.map((a) => [a.variable, `var(--${a.token})`]);

  return {
    aliases,
    groups: {
      fonts,
      breakpoints,
      shadcn,
      palette: palette.figma,
      hues: palette.hues,
      semantic,
      aliases: aliasVars,
      text,
      weights,
      radius,
      shadows,
      blurs,
      containers,
      spacing,
    },
  };
}

export function themeEntries(model: Model): Vars {
  return Object.values(tailwindTheme(model).groups).flat();
}

// ---------------------------------------------------------------------------
// Serialisers
// ---------------------------------------------------------------------------

const block = (selector: string, vars: Vars, extra: string[] = [], indent = "") =>
  [
    `${indent}${selector} {`,
    ...extra.map((l) => `${indent}  ${l}`),
    ...vars.map(([k, v]) => `${indent}  --${k}: ${v};`),
    `${indent}}`,
  ].join("\n");

export const DARK_VARIANT =
  '@custom-variant dark (&:where(.dark, .dark *, [data-theme="dark"], [data-theme="dark"] *));';

export function tokensCss(model: Model) {
  const { tablet, desktop } = viewportVars(model);
  return [
    HEADER,
    block(":root", rootVars(model), ["color-scheme: light;"]),
    `@media (width >= ${MODE_MIN_WIDTH.tablet}) {\n${block(":root", tablet, [], "  ")}\n}`,
    `@media (width >= ${MODE_MIN_WIDTH.desktop}) {\n${block(":root", desktop, [], "  ")}\n}`,
    block('.light,\n[data-theme="light"]', lightScopeVars(model), ["color-scheme: light;"]),
    block('.dark,\n[data-theme="dark"]', darkScopeVars(model), ["color-scheme: dark;"]),
    "",
  ].join("\n\n");
}

export function themeCss(model: Model) {
  const groups = tailwindTheme(model).groups;
  const body = Object.entries(groups)
    .map(([name, vars]) =>
      [`  /* ${name} */`, ...vars.map(([k, v]) => `  --${k}: ${v};`)].join("\n"),
    )
    .join("\n\n");
  return [HEADER, DARK_VARIANT, `@theme inline {\n${body}\n}`, ""].join("\n\n");
}

/** Shared base layer, used by the docs and by dga-style. */
export const BASE_LAYER = {
  "*": { "@apply border-border outline-ring/50": {} },
  html: { "font-family": "var(--font-family-text)" },
  body: { "@apply bg-background text-foreground": {} },
};
